// Command decls lists top-level type/const/var declarations in test-related Go
// files. Parsing ignores build tags, so integration- and e2e-tagged files are
// covered too.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func isTestRelated(path string) bool {
	if strings.HasPrefix(path, "vendor/") {
		return false
	}
	base := filepath.Base(path)
	if strings.HasSuffix(base, "_test.go") {
		return true
	}
	// Test-support packages and helper files.
	testDirs := []string{
		"cmd/entire/cli/integration_test/",
		"cmd/entire/cli/testutil/",
		"cmd/entire/cli/benchutil/",
		"internal/testdirs/",
		"e2e/",
	}
	for _, d := range testDirs {
		if strings.HasPrefix(path, d) {
			return true
		}
	}
	return base == "testhelpers.go" || base == "testing.go"
}

func main() {
	root := "."
	fset := token.NewFileSet()
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if info.Name() == "vendor" || info.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		rel := strings.TrimPrefix(path, "./")
		if !isTestRelated(rel) {
			return nil
		}
		f, perr := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
		if perr != nil {
			fmt.Fprintf(os.Stderr, "parse %s: %v\n", rel, perr)
			return nil
		}
		for _, d := range f.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok {
				continue
			}
			kind := gd.Tok.String()
			if kind != "type" && kind != "const" && kind != "var" {
				continue
			}
			for _, spec := range gd.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					pos := fset.Position(s.Name.Pos())
					fmt.Printf("%s\t%s:%d\t%s\n", kind, rel, pos.Line, s.Name.Name)
				case *ast.ValueSpec:
					for _, n := range s.Names {
						if n.Name == "_" {
							continue
						}
						pos := fset.Position(n.Pos())
						fmt.Printf("%s\t%s:%d\t%s\n", kind, rel, pos.Line, n.Name)
					}
				}
			}
		}
		return nil
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

